-{
-}
+    ensures always(always(p)).satisfied_by(ex),
+{
+    // Unfold `always` twice:
+    //   always(p).satisfied_by(ex) == forall i. p.satisfied_by(ex.suffix(i))
+    //   always(always(p)).satisfied_by(ex) == forall i. always(p).satisfied_by(ex.suffix(i))
+    // And `always(p).satisfied_by(ex.suffix(i))` follows by applying the first forall
+    // to the composed suffix.
+    let _ = ex;
+    assert forall |i: nat| #[trigger] always(p).satisfied_by(ex.suffix(i)) by {
+        // Need to show: forall j. p.satisfied_by((ex.suffix(i)).suffix(j))
+        // which equals: forall j. p.satisfied_by(ex.suffix(i + j)).
+        assert forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(i + j)) by {
+            // From always(p).satisfied_by(ex): p.satisfied_by(ex.suffix(k)) for all k.
+            // Take k = i + j.
+            let k: nat = i + j;
+            assert p.satisfied_by(ex.suffix(k)) by {
+                // Extract the required fact from the assumption.
+                // `always(p).satisfied_by(ex)` is a forall over nat.
+                // Using it at k yields the goal.
+                reveal always(p).satisfied_by(ex);
+            }
+        };
+    };
+}
