 proof fn always_double<T>(ex: Execution<T>, p: TempPred<T>)
     requires always(p).satisfied_by(ex),
     ensures always(always(p)).satisfied_by(ex),
 {
-    forall |i: nat| #[trigger] {
-        p.satisfied_by(ex.suffix(i))
-    }
+    // We just need to show that for all i, always(p).satisfied_by(ex.suffix(i)) holds.
+    // Unfolding the definitions reduces this to instantiating the forall inside always(p).
+    assert forall |i: nat| #[trigger] always(p).satisfied_by(ex.suffix(i)) by {
+        // `always(p).satisfied_by(ex)` means: forall k, p.satisfied_by(ex.suffix(k)).
