+        //   forall j, p.satisfied_by((ex.suffix(i)).suffix(j))
+        // and (ex.suffix(i)).suffix(j) == ex.suffix(i + j).
+        forall |j: nat| #[trigger] {
+            p.satisfied_by(ex.suffix(i + j))
+        }
+    };
 }
